        {"id": "BAU_WERKSTATT:lernpause","kopf": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen. Das finde ich einfach gut.","optionen": [{"text": "Nach etwas Bewegung fällt es uns leichter, wieder aufzupassen.","ok": true,"info": "Dieser Grund erklärt, warum der Vorschlag sinnvoll ist.","warum": [{"text": "Nach etwas Bewegung fällt es uns leichter, wieder aufzupassen.","ok": true},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false},{"text": "Die Pausenkarte hängt an der Tafel.","ok": false}]},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false,"info": "Das passt zum Thema, erklärt aber nicht das Warum."},{"text": "Die Pausenkarte hängt an der Tafel.","ok": false,"info": "Das beschreibt nur ein Detail und ist noch kein Grund."}]}
