        {"id": "BAU_MUEHLE:klassenregel","meinung": "Wir sollten eine feste Reihenfolge beim Sprechen nutzen.","begruendungen": [{"text": "Wenn alle nacheinander sprechen, können wir auch leise Kinder hören.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Niemand wird mitten im Satz von anderen übertönt.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Im Klassenrat gibt es eine Redeliste.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Amira hält eine Redekarte in der Hand.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:dienste","meinung": "Wir sollten die Klassendienste jede Woche wechseln.","begruendungen": [{"text": "Beim Wechsel erledigen nicht immer dieselben Kinder die Arbeit.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Auch unbeliebte Dienste werden beim Wechsel von allen übernommen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Dienste stehen auf einem Plan.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Der Dienstplan hängt neben der Tafel.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:klassenfahrt","meinung": "Wir sollten auf der Klassenfahrt Aufgaben im Team lösen.","begruendungen": [{"text": "Bei Teamaufgaben lernen wir auch andere Kinder aus der Klasse besser kennen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Bei gemeinsamen Aufgaben hört man auch die Ideen neuer Partner.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Klassenfahrt dauert mehrere Tage.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Bei der Wegsuche tragen alle eine Mütze.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:schulhof","meinung": "Wir sollten Spielgeräte in der Pause ausleihen können.","begruendungen": [{"text": "Die Ausleihe ermöglicht Spiele auch ohne eigene Geräte.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Fehlende eigene Spielsachen schließen dann niemanden vom Spiel aus.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Spielgeräte liegen in einer Kiste.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Ivos Springseil hat grüne Griffe.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:sport","meinung": "Wir sollten im Sport verschiedene Spiele ausprobieren.","begruendungen": [{"text": "Verschiedene Spiele geben Kindern mit unterschiedlichen Stärken eine Chance.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Wer beim Laufen nicht schnell ist, kann zum Beispiel beim Zielwerfen gut sein.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Sportspiele haben verschiedene Regeln.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Beim Zielwerfen benutzt Sam einen weichen Ball.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:ags","meinung": "Wir sollten vor der AG-Wahl Schnupperstunden anbieten.","begruendungen": [{"text": "Beim Schnuppern können wir die Tätigkeit vor der Wahl testen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ein eigener Versuch zeigt besser als ein Name, was man gern macht.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die AGs finden nach dem Unterricht statt.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Das Modell steht nach der AG auf dem Regal.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:handys","meinung": "Wir sollten Handys während der Gruppenarbeit weglegen.","begruendungen": [{"text": "Ohne Nachrichten werden wir im Gespräch seltener abgelenkt.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ohne Blick aufs Display bemerkt man Fragen der anderen schneller.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Handys liegen während der Arbeit in Taschen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Jona legt sein Handy in eine blaue Hülle.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:haustiere","meinung": "Wir sollten vor dem Tierkauf einen Pflegeplan machen.","begruendungen": [{"text": "Im Pflegeplan steht, wer das Tier jeden Tag füttert und versorgt.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Auch am Wochenende ist dann klar, wer das Tier füttert.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Auf dem Pflegeplan stehen Namen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Neben dem Plan hängt ein Tierfoto.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:freizeit","meinung": "Wir sollten einen Nachmittag ohne feste Termine lassen.","begruendungen": [{"text": "In freier Zeit können wir selbst ein eigenes Vorhaben beginnen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ohne festen Termin bleibt Zeit, eigene Spiele zu erfinden.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Der Nachmittag hat keinen festen Kurs.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Ayla stellt ihren Karton auf den Tisch.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:fahrrad","meinung": "Wir sollten Fahrräder vor dem Ausflug gemeinsam prüfen.","begruendungen": [{"text": "Beim Test fallen kaputte Bremsen schon vor der Abfahrt auf.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ein vorher entdeckter Fehler kann noch vor der Fahrt behoben werden.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Räder stehen vor dem Ausflug auf dem Hof.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Pauls Fahrrad hat einen blauen Sattel.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:schulweg","meinung": "Wir sollten auf dem Schulweg sichere Stellen zum Überqueren wählen.","begruendungen": [{"text": "An übersichtlichen Stellen sehen wir herankommende Autos rechtzeitig.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Wenn wir die Autos früh sehen, können wir warten, bis die Straße frei ist.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Auf dem Schulweg gibt es mehrere Straßen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "An der Kreuzung steht ein kleiner Laden.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:umwelt","meinung": "Wir sollten in leeren Klassenräumen das Licht ausschalten.","begruendungen": [{"text": "Ausgeschaltete Lampen verbrauchen keinen Strom.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Eine ausgeschaltete Lampe verbraucht in dieser Zeit keinen Strom.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "An der Decke hängen mehrere Lampen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Neben dem Lichtschalter hängt ein Plakat.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:muell","meinung": "Wir sollten Papier getrennt von Essensresten sammeln.","begruendungen": [{"text": "Sauberes Altpapier kann zu neuem Papier verarbeitet werden.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Bananenschalen und Joghurt würden das Altpapier verschmutzen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Für Papier gibt es einen eigenen Eimer.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Der Papiereimer steht neben der Tür.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:ausflug","meinung": "Wir sollten ein Ausflugsziel wählen, das wir mit dem Bus erreichen.","begruendungen": [{"text": "Im Bus kann man auch ohne eigenes Auto zum Ziel mitkommen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Eine gemeinsame Anfahrt hängt nicht vom Auto der Eltern ab.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Der Bus hält vor unserer Schule.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Nuri sitzt im Bus am Fenster.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:klassenfest","meinung": "Wir sollten für das Klassenfest verschiedene Aufgaben anbieten.","begruendungen": [{"text": "Bei verschiedenen Aufgaben kann auch mithelfen, wer nicht auftreten möchte.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ein Kind kann Einladungen malen, während ein anderes auf der Bühne singt.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Auf dem Fest gibt es mehrere Aufgaben.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Luz legt die Einladungen in einen Karton.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:gruppenarbeit","meinung": "Wir sollten in Gruppen klare Aufgaben absprechen.","begruendungen": [{"text": "Durch Absprachen kennt jeder seinen eigenen Teil der Aufgabe.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Wenn klar ist, wer Bilder sucht und wer schreibt, wird kein Teil vergessen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "In der Gruppe sitzen mehrere Kinder.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Cems Heft liegt neben der Schere.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:bibliothek","meinung": "Wir sollten die Regale unserer Klassenbibliothek nach Themen beschriften.","begruendungen": [{"text": "Die Schilder zeigen sofort, welches Thema ein Regal enthält.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Wer ein Thema sucht, muss dann nicht jedes Buch einzeln herausziehen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Bücher stehen in mehreren Regalen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Das Schild ist aus Pappe.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:schulessen","meinung": "Wir sollten beim Schulessen kleine erste Portionen wählen.","begruendungen": [{"text": "Wer erst wenig nimmt und bei Hunger nachholt, lässt weniger Essen übrig.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Auf dem Teller bleibt weniger zurück, wenn die Menge zum Hunger passt.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "An der Ausgabe stehen Teller bereit.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Sibel bekommt ihren Reis mit einer Kelle.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:trinken","meinung": "Wir sollten Wasserflaschen im Klassenraum auffüllen können.","begruendungen": [{"text": "Wir können unsere leere Flasche nachfüllen und müssen nicht durstig bleiben.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Nach dem Sport können wir Wasser nachfüllen, statt bis zu Hause zu warten.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Unsere Flaschen haben verschiedene Farben.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Ravis Flasche hat einen gelben Aufkleber.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:lesezeit","meinung": "Wir sollten eine kurze stille Lesezeit einführen.","begruendungen": [{"text": "Beim stillen Lesen unterbricht uns kein Gespräch.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ohne Unterbrechung können wir einer Geschichte leichter folgen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Beim Lesen liegen Bücher auf den Tischen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Majas Buch hat einen grünen Umschlag.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:partnerwahl","meinung": "Wir sollten bei kurzen Partneraufgaben gelegentlich auslosen.","begruendungen": [{"text": "Durch das Los arbeiten wir auch mit Kindern, die wir seltener wählen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Neue Partner zeigen, wie andere Kinder an dieselbe Aufgabe herangehen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Bei einer Partneraufgabe arbeiten zwei Kinder zusammen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Die Lose liegen in einem Stoffbeutel.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:ordnung","meinung": "Wir sollten gemeinsam benutztes Material fest einsortieren.","begruendungen": [{"text": "Ein fester Platz zeigt allen, wo Schere und Kleber liegen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Ein fester Platz hilft auch Kindern, die das Material nicht weggeräumt haben.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Scheren und Kleber sind Bastelmaterial.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Zoes Materialkiste hat einen Deckel.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:spielregeln","meinung": "Wir sollten Spielregeln vor dem Turnier gemeinsam klären.","begruendungen": [{"text": "Nach dem Klären wissen beide Teams, welche Regeln gelten.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Bei einer strittigen Entscheidung können beide Teams in denselben Regeln nachsehen.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Beim Turnier spielen mehrere Teams.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Die Spielregeln stehen auf einem Plakat.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:radstaender","meinung": "Wir sollten Fahrräder an festen Plätzen abstellen.","begruendungen": [{"text": "Mit festen Plätzen steht kein Rad vor unserer Eingangstür.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Dann können alle durch die Eingangstür gehen, ohne Räder wegzuschieben.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Fahrradständer stehen neben der Schule.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Amins Fahrrad ist rot.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:tauschregal","meinung": "Wir sollten ein Tauschregal für brauchbare Schulsachen aufstellen.","begruendungen": [{"text": "Im Regal können andere die noch guten Sachen weiterbenutzen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Was weiterverwendet wird, muss nicht gleich neu gekauft werden.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Im Tauschregal liegen Schulsachen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Das Regal hat vier Fächer.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]},
        {"id": "BAU_MUEHLE:lernpause","meinung": "Wir sollten bei langen Arbeitsphasen kurze Bewegungspausen machen.","begruendungen": [{"text": "Nach etwas Bewegung fällt es uns leichter, wieder aufzupassen.","ok": true,"info": "Das erklärt, warum der Vorschlag hilft."},{"text": "Nach dem Strecken können wir uns wieder auf die nächste Aufgabe konzentrieren.","ok": true,"info": "Auch dieser Satz erklärt einen Nutzen des Vorschlags."},{"text": "Die Bewegungspause liegt zwischen zwei Arbeitsphasen.","ok": false,"info": "Das beschreibt das Thema, nennt aber noch keinen Grund für den Vorschlag."},{"text": "Die Pausenkarte hängt an der Tafel.","ok": false,"info": "Das ist ein Detail, aber keine Begründung für die Meinung."}]}
